import{z as s,x as l,o as t,c as d,q as n,j as A,D as r,d as e,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"代码评审","description":"","frontmatter":{"title":"代码评审","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-code-review.md","filePath":"quant/rc2-code-review.md","lastUpdated":1791413859000}'),p={name:"quant/rc2-code-review.md"};function c(h,a,f,m,D,u){const B=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="代码评审" tabindex="-1">代码评审 <a class="header-anchor" href="#代码评审" aria-label="Permalink to &quot;代码评审&quot;">​</a></h1><div class="epigraph"><p>评审的产出不是挑错的数量，是团队里有多少人从此懂了这段代码为什么这样写。</p><footer>—— 据 Sadowski et al., Modern Code Review: A Case Study at Google, 2018；Bacchelli and Bird, Expectations, Outcomes, and Challenges of Modern Code Review, ICSE, 2013 整理</footer></div><p><a href="/quant/rc2-repro-package-standard">上一课</a>让陌生人能盲跑你的研究。团队里其实没有陌生人，只有分工——而分工制造盲区：写信号的不清洗数据，清洗数据的不看执行，每人守着自己那一段的正确性，接缝处没人负责。评审是把接缝摊开的机制，也是「协作」单元的第一课。本课写研究代码的评审怎么评：换掉清单，不拆门槛。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>研究评审有两个对称错误。一个是「研究代码不用评审」：代码短命、跑完就扔，评了浪费——代价是泄漏与幸存者偏差畅通无阻地流向结论，因为错误的收益率从来不体现在代码寿命上，体现在决策上。另一个是对称的：用生产清单评审研究代码——问测试覆盖率、问抽象层级、问命名规范——把探索速度拖死，研究变成写工程文档。两个错误共享同一个误判：以为评审的内容是「代码质量」。评审真正要接住的是<strong>量化专属的错误类</strong>，它们在普通工程清单里根本不存在。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="量化评审清单" tabindex="-1">量化评审清单 <a class="header-anchor" href="#量化评审清单" aria-label="Permalink to &quot;量化评审清单&quot;">​</a></h3><p>四条清单比风格清单值钱。<strong>泄漏</strong>：归一化是否用了全样本统计量、标签是否用收盘价对齐到当天、特征时点是否早于决策时点——未来信息的入口全是接缝。<strong>幸存者</strong>：universe 是否用今天的成分表回过去，退市与停牌是否进样本。<strong>对齐</strong>：as-of 取数、时区、复权口径与数据版本引用是否一致——<a href="/quant/de-data-versioning">数据版本化</a>的修正静默，对齐错了不报错。<strong>配置漂移</strong>：跑的参数与<a href="/quant/rc2-experiment-management">实验管理</a>登记的指纹是否同一次运行——改参不换指纹，台账立刻失真。</p><p><span class="marginnote">幸存者偏差翻译一下：只用「今天还活着」的成分股回测过去，等于只统计赢家——退市、被并购、长期停牌的名字被悄悄删掉，收益率系统性偏高。它不报任何错，所以只能靠评审清单专门问一句「退市的进样本了吗」。</span></p><p><span class="marginnote">直觉类比：泄漏就是考试前偷看了标准答案——回测分数漂亮得不像话，实盘立刻打回原形。最常见的一处是用当天收盘价造特征、又用当天收盘价算收益，等于用「已知的未来」去预测「同一个未来」。</span></p>',10)),(t(),A(i,null,{default:r(()=>[o(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHG%5B%22%E5%8F%98%E6%9B%B4%20diff%22%5D%20--%3E%20GEN%5B%22%E9%80%9A%E7%94%A8%E9%97%A8%EF%BC%9A%E5%8F%AF%E9%87%8D%E8%B7%91%20%E4%BE%9D%E8%B5%96%E9%94%81%22%5D%0A%20%20GEN%20--%3E%20QUANT%5B%22%E9%87%8F%E5%8C%96%E6%B8%85%E5%8D%95%EF%BC%9A%E6%B3%84%E6%BC%8F%20%E5%B9%B8%E5%AD%98%E8%80%85%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20GEN%20--%3E%20CFG%5B%22%E6%8C%87%E7%BA%B9%E6%A0%B8%E5%AF%B9%EF%BC%9A%E8%B7%91%E7%9A%84%E5%8D%B3%E7%99%BB%E8%AE%B0%E7%9A%84%22%5D%0A%20%20QUANT%20--%3E%20MERGE%5B%22%E5%90%88%E5%B9%B6%22%5D%0A%20%20CFG%20--%3E%20MERGE%0A%20%20MERGE%20--%3E%20REG%5B%22%E7%99%BB%E8%AE%B0%E6%9B%B4%E6%96%B0%20%E5%8F%B0%E8%B4%A6%E5%BC%95%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("评审在研究里仍然划算，算的不是 defect 率，是"),E("strong",null,"拦截位置的成本"),e("。一个带泄漏的因子，在 diff 阶段拦住的成本是一行注释；在定案评审拦住是一次返工；在实盘拦住是一笔亏空加一次复盘。实证研究也支持同样的重心：Bacchelli 和 Bird 对开发者的调查发现，评审实际收益里缺陷发现占比有限，代码改进与知识传递占大头；Google 的案例把评审当成知识扩散的主要渠道，结论是小步高频——单次几百行以内，意见密度与通过速度都最好。落到研究团队：评审单位小，意味着「一次只评一个假设的一次改动」，不是月末集中评一千行。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"选评审人的口径：优先让懂数据接缝的人评，而不是职位最近的同事。量化错误的重心在数据侧——同样的 diff，做过清洗的人一眼看出 as-of 方向反了，没做过的人只会把变量名改得更长。")],-1)),(t(),A(i,null,{default:r(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAK%5B%22%E4%B8%80%E4%B8%AA%E5%B8%A6%E6%B3%84%E6%BC%8F%E7%9A%84%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20A%5B%22diff%20%E9%98%B6%E6%AE%B5%E6%8B%A6%E4%BD%8F%EF%BC%9A%E4%B8%80%E8%A1%8C%E6%B3%A8%E9%87%8A%22%5D%0A%20%20A%20--%3E%20B%5B%22%E5%AE%9A%E6%A1%88%E8%AF%84%E5%AE%A1%E6%8B%A6%E4%BD%8F%EF%BC%9A%E4%B8%80%E6%AC%A1%E8%BF%94%E5%B7%A5%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%AE%9E%E7%9B%98%E6%89%8D%E6%8B%A6%E4%BD%8F%EF%BC%9A%E4%B8%80%E7%AC%94%E4%BA%8F%E7%A9%BA%E5%8A%A0%E4%B8%80%E6%AC%A1%E5%A4%8D%E7%9B%98%22%5D%0A%20%20SMALL%5B%22%E5%8D%95%E6%AC%A1%E8%AF%84%E5%AE%A1%E5%87%A0%E7%99%BE%E8%A1%8C%E4%BB%A5%E5%86%85%22%5D%20--%3E%20GOOD%5B%22%E6%84%8F%E8%A7%81%E5%AF%86%E5%BA%A6%E4%B8%8E%E9%80%9A%E8%BF%87%E9%80%9F%E5%BA%A6%E9%83%BD%E6%9C%80%E5%A5%BD%22%5D%0A%20%20METRIC%5B%22%E5%BA%A6%E9%87%8F%EF%BC%9A%E5%93%8D%E5%BA%94%E6%97%B6%E9%97%B4%E4%B8%8E%E6%B8%85%E5%8D%95%E5%91%BD%E4%B8%AD%E7%8E%87%22%5D%20--%3E%20NOT%5B%22%E4%B8%8D%E6%98%AF%E6%84%8F%E8%A7%81%E6%9D%A1%E6%95%B0%22%5D%0A%20%20ZERO%5B%22%E9%9B%B6%E6%84%8F%E8%A7%81%E7%9A%84%E8%AF%84%E5%AE%A1%22%5D%20--%3E%20ASK%5B%22%E5%85%88%E9%97%AE%E6%98%AF%E7%9C%9F%E5%B9%B2%E5%87%80%EF%BC%8C%E8%BF%98%E6%98%AF%E6%B2%A1%E4%BA%BA%E7%9C%8B%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h3 id="节奏与归属" tabindex="-1">节奏与归属 <a class="header-anchor" href="#节奏与归属" aria-label="Permalink to &quot;节奏与归属&quot;">​</a></h3><p>节奏上，评审嵌入<a href="/quant/rc2-code-standards">规范</a>的显式性约束：diff 里出现硬编码路径、改参不动配置，就是清单项，不需要评审人额外动用判断。归属上，评审不替代台账与判据：\\(N\\) 完整与否是<a href="/quant/rc2-experiment-management">实验管理</a>的事，假设是否值得做是提案评审（后课委员会）的事；代码评审只答一个问题——<strong>这次改动记录的实验，是不是它声称的那个实验</strong>。品味之争不在代码评审里裁，裁不动也没必要：让它留在文档与提案层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>评审不能验证结果的正确性：跑一遍对不上基准是复现的事（上一课），对得上基准不代表没有泄漏——评审人是在读逻辑，不是在证明。评审也不是门禁的替代：候选升格的独立复跑与台账核对属于定案流程，评审通过不等于可以上线。最后，评审有自己的失效模式：走过场式的「LGTM 接力」与拖延式的「压两周不回」同样致命——前者让清单形同虚设，后者把研究节奏拖垮；度量的是响应时间与清单命中率，不是意见条数。</p><p><span class="marginnote">常见误区：把「LGTM 接力」当成评审通过。人人点头、无人负责时，清单形同虚设，泄漏照样流向结论。零意见的评审往往不是「代码很干净」，而是「没人真看」——所以度量评审要看响应时间与清单命中率，不看意见条数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两个对称错误：不评（泄漏流向决策）与生产式评（探索速度拖死）；要换清单，不要拆门槛。</li><li>量化清单四条：泄漏、幸存者、对齐、配置漂移；重心全在数据与配置的接缝上。</li><li>评审的收益大头是知识传递与改进，不只是挑错；小步高频，单次几百行以内。</li><li>选人看数据经验；代码评审只答「记录的实验是不是声称的那个实验」，品味上交提案层。</li><li>出处：Bacchelli and Bird, <em>ICSE</em>, 2013；Sadowski et al., 2018；站内<a href="/quant/rc2-experiment-management">实验管理</a>、<a href="/quant/de-data-versioning">数据版本化</a>各课。</li></ul>',7))])}const g=s(p,[["render",c]]);export{F as __pageData,g as default};
